package com.civicfix.model;
import jakarta.persistence.*;import java.time.Instant;
@Entity public class Complaint { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private String referenceCode; @Column(nullable=false) private String title; @Column(length=3000,nullable=false) private String description; private String category; @Enumerated(EnumType.STRING) private Priority priority; @Enumerated(EnumType.STRING) private ComplaintStatus status=ComplaintStatus.UNDER_REVIEW; private String department; private Double latitude; private Double longitude; private String address; private String imageUrl; private Integer aiConfidence; private Integer urgencyScore; @Column(length=1000) private String triageRationale; private String triageVersion; private boolean triageReviewRequired; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now(); @ManyToOne(fetch=FetchType.LAZY) private User reporter; public Long getId(){return id;} public String getReferenceCode(){return referenceCode;} public void setReferenceCode(String v){referenceCode=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public Priority getPriority(){return priority;} public void setPriority(Priority v){priority=v;} public ComplaintStatus getStatus(){return status;} public void setStatus(ComplaintStatus v){status=v;updatedAt=Instant.now();} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public Double getLatitude(){return latitude;} public void setLatitude(Double v){latitude=v;} public Double getLongitude(){return longitude;} public void setLongitude(Double v){longitude=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} public Integer getAiConfidence(){return aiConfidence;} public void setAiConfidence(Integer v){aiConfidence=v;} public Integer getUrgencyScore(){return urgencyScore;} public void setUrgencyScore(Integer v){urgencyScore=v;} public String getTriageRationale(){return triageRationale;} public void setTriageRationale(String v){triageRationale=v;} public String getTriageVersion(){return triageVersion;} public void setTriageVersion(String v){triageVersion=v;} public boolean isTriageReviewRequired(){return triageReviewRequired;} public void setTriageReviewRequired(boolean v){triageReviewRequired=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public User getReporter(){return reporter;} public void setReporter(User v){reporter=v;} }

